import{_ as a,o as r,c as o,a4 as t}from"./chunks/framework.CmuCl-jw.js";const m=JSON.parse('{"title":"Observatory Headquarters","description":"","frontmatter":{},"headers":[],"relativePath":"apps/headquarters/index.md","filePath":"apps/headquarters/index.md"}'),s={name:"apps/headquarters/index.md"};function n(i,e,l,d,h,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="observatory-headquarters" tabindex="-1">Observatory Headquarters <a class="header-anchor" href="#observatory-headquarters" aria-label="Permalink to “Observatory Headquarters”">​</a></h1><p>Every Arcsecond.local installation is <strong>multi-user by design</strong>. You do not opt into a separate &quot;organisation&quot; or &quot;portal&quot; product — the moment you run Arcsecond.local, you are running a shared space for your whole observatory, science group, university, planetarium or astronomy club. <strong>Observatory Headquarters</strong> is the app where that shared life is managed.</p><blockquote><p>&quot;All astronomical observatories in the world have in common the needs to prepare and plan observations, organise and execute night operations, then store, package and distribute data.&quot;</p><p>— Cédric Foellmi, Ph.D. (former <a href="https://www.eso.org/sci/publications/messenger/archive/no.121-sep05/messenger-no121-69-69.pdf" target="_blank" rel="noreferrer">ESO Fellow in La Silla</a>, and Arcsecond Founder)</p></blockquote><p>The other three apps — <a href="/apps/night-studio/">Night Studio</a>, the <a href="/apps/control-room/">Control Room</a> and <a href="/apps/data/">Data Grand Central</a> — are the same for <strong>every member</strong> of your install. Observatory Headquarters adds the organisation-wide layer on top of them.</p><h2 id="what-it-gives-you" tabindex="-1">What it gives you <a class="header-anchor" href="#what-it-gives-you" aria-label="Permalink to “What it gives you”">​</a></h2><ul><li><strong>A single home for the whole life of your observatory</strong> — the history of all observations, observers, targets and observing nights, and a modern data archive built on the same APIs that power the rest of the platform, even for data located elsewhere (see <a href="/apps/data/external-storages">External Storages</a>).</li><li><strong>An unlimited number of members</strong>, with a clear, easy-to-manage <a href="./permissions">5-level permission scheme</a> to control who can do what and who can access what.</li><li><strong>Sharing</strong>, from a private dataset between two members up to a customizable public page exposing selected data to the world.</li><li><strong>An Observatory Schedule</strong> to manage what happens across your telescopes and observers over time — switchable between a calendar view, a telescopes timeline or an observers timeline, including recurring events.</li></ul><h2 id="members-and-roles" tabindex="-1">Members and roles <a class="header-anchor" href="#members-and-roles" aria-label="Permalink to “Members and roles”">​</a></h2><p>Membership and access are governed by five purely-hierarchical roles, from <code>Anonymous</code> up to <code>Superadmin</code>. The full capability matrix is on the <a href="./permissions">Permissions &amp; Roles</a> page.</p>',8)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
